{
  "positionId": "P03",
  "interviews": [
    {
      "categoryId": "P03-C1",
      "itemId": "P03-C1-I1",
      "interviewBlueprint": {
        "questionIntent": "투약 전 확인 절차를 지키고, 처방이 의심스러울 때 투약을 멈춰 담당자에게 확인하는 행동을 검증한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "진통제 처방 용량이 평소의 두 배로 입력된 상황을 알아차리고 투약을 멈춘 사례.",
          "task": "환자에게 처방대로 안전하게 투약하기 위해 처방의 이상 여부를 확인해야 했던 상황.",
          "action": "처방과 환자, 약물·용량·경로·시간을 확인하고 의심되거나 확인되지 않는 부분이 있으면 투약을 보류한 뒤 담당자에게 확인한다.",
          "result": "담당의 확인으로 입력 오류를 발견하고 바로잡은 결과."
        },
        "expectedEvidence": [
          "처방 용량이 평소와 다르다는 점을 이상 징후로 알아차린 근거",
          "투약 전에 처방과 환자, 약물·용량·경로·시간을 확인한 절차",
          "의심되는 처방에 대해 투약을 멈추고 담당의에게 확인한 행동",
          "확인 결과 입력 오류가 발견되어 바로잡힌 경위"
        ]
      },
      "question": "진통제 용량이 평소의 두 배로 입력된 것을 보고 투약을 멈추셨다고 했는데요. 투약 오류를 막기 위해 어떤 확인 절차를 거쳐 처방의 이상 여부를 판단하셨나요?",
      "answerTip": "상황과 본인이 맡은 역할을 먼저 짚어 보세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "처방에서 무엇이 이상했는지 구체적으로 설명하고, 환자와 약물·용량·경로·시간 확인 절차를 제시한다.",
            "의심되는 처방을 그대로 수행하지 않고 투약을 멈춰 담당의에게 확인한 행동이 드러난다.",
            "확인 결과 입력 오류가 발견되고 바로잡힌 경위를 설명한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "평소와 다른 용량을 알아차려 투약을 멈추고 담당의에게 확인한 핵심 행동은 확인되지만, 확인 절차나 판단 근거가 일부 빠져 있다.",
            "오류가 확인되었다고 말하지만, 확인 결과나 바로잡힌 경위가 충분히 구체적이지 않다."
          ]
        },
        "poor": {
          "criteria": [
            "투약 전 확인 절차나 처방 이상을 판단한 근거가 드러나지 않는다.",
            "의심되는 처방을 멈추고 담당자에게 확인한 행동이 없거나, 질문 의도와 무관한 답변을 한다."
          ]
        }
      }
    },
    {
      "categoryId": "P03-C1",
      "itemId": "P03-C1-I2",
      "interviewBlueprint": {
        "questionIntent": "환자 상태 변화를 관찰하고 그 근거를 간호 기록에 정확히 남기는 행동을 검증한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "정형외과 병동에서 활력징후와 통증을 관찰하고 기록하던 중 환자 상태에 변화가 있었던 사례.",
          "task": "정해진 주기로 환자 상태를 확인하고 변화가 간호 기록에 정확히 반영되도록 하는 일.",
          "action": "활력징후, 통증, 의식 수준 등 확인한 상태 변화와 관찰 근거를 기록하고, 이상 징후가 있으면 담당 의사에게 보고한 뒤 다음 근무자에게 인수인계한다.",
          "result": "관찰된 변화가 기록과 보고, 인수인계로 전달되어 후속 근무자가 환자 상태를 이어서 파악할 수 있었는지 확인한다."
        },
        "expectedEvidence": [
          "어떤 환자 상태 변화를 관찰했는지와 관찰 시점 또는 주기",
          "활력징후, 통증, 의식 수준 등 기록 내용과 그 판단 근거",
          "이상 징후를 간호 기록에 정확히 남긴 방법",
          "이상 징후를 담당 의사에게 보고하고 다음 근무자에게 인수인계한 내용",
          "기록과 보고, 인수인계가 후속 확인에 어떻게 이어졌는지"
        ]
      },
      "question": "정형외과 병동에서 활력징후와 통증을 관찰해 기록하셨다고 했는데요. 상태 변화가 있었던 사례 하나를 골라, 어떤 근거로 간호 기록에 남길 변화를 판단하셨나요?",
      "answerTip": "한 사례를 골라 본인의 행동을 중심으로 답해 보세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "환자 상태 변화와 관찰한 근거를 구체적으로 설명하고, 정해진 주기에 맞춰 확인한 내용을 간호 기록에 정확히 남긴다.",
            "이상 징후를 담당 의사에게 보고하고 다음 근무자에게 인수인계한 내용과 그 결과가 드러난다."
          ]
        },
        "acceptable": {
          "criteria": [
            "환자 상태 변화와 기록한 내용은 확인되지만, 관찰 근거·기록의 구체성·확인 주기 중 일부가 부족하다.",
            "보고 또는 인수인계 중 일부는 설명하지만, 후속 근무자에게 변화가 전달된 경위가 충분히 드러나지 않는다."
          ]
        },
        "poor": {
          "criteria": [
            "환자 상태 변화의 관찰 근거나 간호 기록에 남긴 내용이 구체적으로 확인되지 않는다.",
            "이상 징후를 보고하고 인수인계한 행동이 드러나지 않거나, 질문 의도와 무관한 답변을 한다."
          ]
        }
      }
    }
  ]
}
